    private function ensureSchema():void{$columns=$this->pdo->query('SHOW COLUMNS FROM daily_disbursement_point_settings')->fetchAll(PDO::FETCH_COLUMN,0)?:[];$alter=[];$defs=['point_stopped_cta_body'=>'TEXT NULL','point_stopped_cta_sid'=>'VARCHAR(34) NULL','twilio_account_sid'=>'VARCHAR(80) NULL','twilio_auth_token_encrypted'=>'TEXT NULL','twilio_whatsapp_from'=>'VARCHAR(40) NULL','twilio_waba_id'=>'VARCHAR(40) NULL','meta_business_id'=>'VARCHAR(40) NULL','dg_phone_locked_at'=>'DATETIME NULL','twilio_configured_at'=>'DATETIME NULL'];foreach($defs as $name=>$definition)if(!in_array($name,$columns,true))$alter[]="ADD COLUMN $name $definition";if($alter)$this->pdo->exec('ALTER TABLE daily_disbursement_point_settings '.implode(',',$alter));}
