    public function save(array $input,int $userId,bool $canChangeDg=false):void{$current=$this->pdo->query('SELECT * FROM daily_disbursement_point_settings WHERE id=1')->fetch(PDO::FETCH_ASSOC)?:[];$dg=trim((string)($input['dg_phone']??''));if(trim((string)($current['dg_whatsapp_phone']??''))===''&&$dg!=='')$dg=$this->normalizePhone($dg);elseif($dg!==''&&$this->normalizePhone($dg)!==(string)$current['dg_whatsapp_phone']&&!$canChangeDg)throw new RuntimeException('Le numéro du DG est verrouillé après son premier enregistrement.');else$dg=(string)($current['dg_whatsapp_phone']??'');$sid=trim((string)($input['account_sid']??''));if($sid!==''&&!preg_match('/^AC[a-fA-F0-9]{32}$/',$sid))throw new RuntimeException('Le SID Twilio doit commencer par AC et contenir 34 caractères.');$sender=$this->normalizePhone((string)($input['sender_phone']??''));$token=trim((string)($input['auth_token']??''));$encrypted=(string)($current['twilio_auth_token_encrypted']??'');if($token!==''){$encrypted=$this->encrypt($token);if($encrypted==='')throw new RuntimeException('Le chiffrement des secrets est indisponible. Configurez TWILIO_CONFIG_KEY ou MAIL_PASSWORD_KEY.');}$ctaBody=DailyPointWhatsAppTemplateService::BODY;$ctaSid=trim((string)($input['point_stopped_cta_sid']??$current['point_stopped_cta_sid']??''));
        if($ctaSid!==''){
