    public function credentials():array{$row=$this->pdo->query('SELECT point_stopped_cta_body,point_stopped_cta_sid,twilio_account_sid,twilio_auth_token_encrypted,twilio_whatsapp_from FROM daily_disbursement_point_settings WHERE id=1')->fetch(PDO::FETCH_ASSOC)?:[];EnvConfig::loadFromDirectory(__DIR__);$dbSid=trim((string)($row['twilio_account_sid']??''));$dbToken=$this->decrypt((string)($row['twilio_auth_token_encrypted']??''));$envSid=trim((string)(getenv('TWILIO_ACCOUNT_SID')?:getenv('TWILIO_SID')?:''));$envToken=trim((string)(getenv('TWILIO_AUTH_TOKEN')?:getenv('TWILIO_TOKEN')?:''));if($dbSid!==''&&$dbToken!==''){$sid=$dbSid;$token=$dbToken;$source='interface';}else{$sid=$envSid;$token=$envToken;$source=$sid!==''&&$token!==''?'environnement':'incomplet';}$from=trim((string)($row['twilio_whatsapp_from']??''))?:trim((string)(getenv('TWILIO_WHATSAPP_FROM')?:''));if($from!==''&&!str_starts_with($from,'whatsapp:'))$from='whatsapp:'.$from;return['point_stopped_cta_body'=>$row['point_stopped_cta_body']??DailyPointWhatsAppTemplateService::BODY,'sid'=>$sid,'token'=>$token,'from'=>$from,'credential_source'=>$source,'point_stopped_content_sid'=>trim((string)($row['point_stopped_cta_sid']??''))?:self::POINT_STOPPED_TEMPLATE_SID,'point_stopped_template_name'=>!empty($row['point_stopped_cta_sid'])?'FINEA · signature du point':self::POINT_STOPPED_TEMPLATE_NAME,'point_stopped_has_variables'=>!empty($row['point_stopped_cta_sid'])];}
    private function normalizePhone(string $phone):string{$phone=preg_replace('/^whatsapp:/i','',trim($phone));$digits=preg_replace('/\D+/','',$phone);if(str_starts_with($digits,'00'))$digits=substr($digits,2);if($phone!==''&&!str_starts_with($phone,'+')&&!str_starts_with($digits,'225'))$digits='225'.$digits;$phone='+'.$digits;if(!preg_match('/^\+[1-9]\d{7,14}$/',$phone))throw new RuntimeException('Numéro WhatsApp invalide. Utilisez le format international.');return$phone;}
    private function key():string{$raw=trim((string)(EnvConfig::get('TWILIO_CONFIG_KEY','')?:EnvConfig::get('MAIL_PASSWORD_KEY','')));return$raw!==''?hash('sha256',$raw,true):'';}
    private function encrypt(string $plain):string{$key=$this->key();if($key===''||!function_exists('openssl_encrypt'))return'';$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,self::CIPHER,$key,OPENSSL_RAW_DATA,$iv,$tag);return$cipher===false||$tag===''?'':base64_encode($iv).':'.base64_encode($tag).':'.base64_encode($cipher);}
    private function decrypt(string $packed):string{if($packed==='')return'';$key=$this->key();$parts=explode(':',$packed);if($key===''||count($parts)!==3||!function_exists('openssl_decrypt'))return'';[$iv,$tag,$cipher]=array_map(static fn($v)=>base64_decode($v,true),$parts);if($iv===false||$tag===false||$cipher===false)return'';$plain=openssl_decrypt($cipher,self::CIPHER,$key,OPENSSL_RAW_DATA,$iv,$tag);return$plain===false?'':$plain;}
